-- 0031: мини-проверка после лекции — только вопросы курсов. Убираются связки с вопросами переаттестации (r6-*, reatt-*, категория «Переаттестация…», вопросы баз);
-- у затронутых лекций набор пересобран tools/content/lecture-quiz.js (добор вопросами курсов; если подходящих нет — у лекции проверки нет).
DELETE FROM lecture_quiz WHERE question_id IN (SELECT q.id FROM lecture_quiz lq JOIN questions q ON q.id = lq.question_id WHERE q.ext_id LIKE 'r6-%' OR q.ext_id LIKE 'reatt%' OR q.base IS NOT NULL OR q.category LIKE 'Переаттестация%');
DELETE FROM lecture_quiz WHERE lecture_id IN (37, 83, 86, 90, 97, 98, 99, 105, 109);
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '- ГУ ВП — **высший надзорный орган внутри бригады**: ему предоставлено право осуществлять полный надзор за соблюдением законодательства РФ, нормативных правовых актов, военных доктрин и уставов военнослужащими (п. 5.1). - ГУ ВП — **основной уполномоченный орган** на привлечение военнослужащих к дисциплинарной ответственности, внесение отметок в личные дела, возбуждение и проведение расследований, формирование контрольного дела и материалов для передачи в суд (п. 5.2). - ГУ ВП — **высший орган Военной полиции** в составе 1-й Московской мотострелковой бригады; контролирует работу входящих в него' FROM lectures l, questions q WHERE l.id = 37 AND l.title = 'Лекция 1. ГУ ВП: место в бригаде и структура' AND q.id = 1136 AND q.ext_id = 'osnovy-q09';
