INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '1. **Военная комендатура** — правопорядок и воинская дисциплина на территории части и за её пределами, жалобы, взыскания, гауптвахта. 2. **Батальон военной полиции** — орган дознания бригады: патрули, розыск и задержание, охрана места преступления, розыск похищенного имущества.' FROM lectures l, questions q WHERE l.id = 37 AND l.title = 'Лекция 1. ГУ ВП: место в бригаде и структура' AND q.id = 1140 AND q.ext_id = 'osnovy-q13';
